syntax:
std::set<int> mySet = {1, 2, 3};
// Iterator declaration and usage with implementation notes:
auto it = mySet.begin();  // 'begin()' returns a bidirectional iterator, typically a typedef for a class wrapping a node pointer.
++it;  // Increments the iterator to the next in-order element; implemented as a member function that traverses to the successor node in the red-black tree.
--it;  // Decrements to the previous element; involves traversing to the predecessor.
*it;   // Dereferences the iterator; returns a const reference to the element, as sets provide const access to maintain ordering.

code_example:
#include <iostream>
#include <set>

int main() {
    std::set<int> mySet = {3, 1, 2};  // Internally stored as a balanced binary search tree
    for (auto it = mySet.begin(); it != mySet.end(); ++it) {
        std::cout << *it << std::endl;  // Traverse and print elements
    }
    return 0;
}
